/**
 * Same-origin, compact, independently validated Cardmarket printing prices.
 *
 * Generated by scripts/build-cardmarket-verified.mjs from public Cardmarket
 * product/price exports AND independently numbered set cards. No collector
 * information is published, and the client never downloads the full 30 MB
 * upstream exports. Prices are broad market guides, NOT NM or German listings.
 */
import { numberKey } from '../domain/personal';

type Basis = 'trend' | 'avg7' | 'avg30' | 'avg';
type PricingRow = [number, number, Basis, string, string];
interface VerifiedDailyGuide {
  schemaVersion: number;
  sourceCreatedAt: string;
  currency: string;
  sets: Record<
    string,
    { status: string; pricedPrints?: number }
  >;
  cards: Record<string, PricingRow>;
}
let cache:
  | {
      until: number;
      value: Promise<VerifiedDailyGuide | undefined>;
    }
  | undefined;

async function loadGuide(): Promise<VerifiedDailyGuide | undefined> {
  if (cache && cache.until > Date.now()) return cache.value;
  const pending = (async () => {
    try {
      const response = await fetch(
        `${import.meta.env.BASE_URL}assets/prices/cardmarket-verified.json`,
        {
          cache: 'no-store',
          signal: AbortSignal.timeout(8000),
        },
      );
      if (!response.ok) return undefined;
      const data: unknown = await response.json();
      if (!data || typeof data !== 'object') return undefined;
      const guide = data as VerifiedDailyGuide;
      if (
        guide.schemaVersion !== 1 ||
        guide.currency !== 'EUR' ||
        !guide.cards ||
        !guide.sets ||
        typeof guide.sourceCreatedAt !== 'string'
      )
        return undefined;
      return guide;
    } catch {
      // An absent or offline daily guide cannot break the collector PWA.
      return undefined;
    }
  })();
  cache = { until: Date.now() + 5 * 60 * 1000, value: pending };
  return pending;
}

export interface OfficialPrintingReference {
  productId: number;
  url: string;
  price?: {
    amount: number;
    updated: string;
    basis: Basis;
    provenance: 'official-export';
  };
}

export async function officialCardmarketReference(
  card: {
    id: string;
    setId: string;
    localId: string;
    language: string;
  },
): Promise<OfficialPrintingReference | undefined> {
  if (
    card.language !== 'de' &&
    card.language !== 'en'
  )
    return undefined;
  const guide = await loadGuide();
  if (
    guide?.sets[card.setId]?.status !== 'validated' ||
    card.id.slice(0, card.id.lastIndexOf('-')) !== card.setId
  ) return undefined;
  const row = guide.cards[card.id];
  if (
    !Array.isArray(row) ||
    row.length !== 5 ||
    !Number.isSafeInteger(row[0]) ||
    row[0] <= 0 ||
    numberKey(card.localId) !== numberKey(row[4]) ||
    !['trend','avg7','avg30','avg'].includes(row[2]) ||
    typeof row[3] !== 'string' ||
    !row[3]
  )
    return undefined;
  const productId = row[0];
  const observed = Date.parse(guide.sourceCreatedAt);
  const age = Date.now() - observed;
  // Keep a verified product ID available even after guide expiry, but do
  // not present an outdated quote as today's portfolio value.
  const fresh = Number.isFinite(age) && age >= -300000 && age < 72 * 3600000;
  const amount = row[1];
  const price =
    fresh &&
    Number.isFinite(amount) &&
    amount > 0 &&
    amount < 100000
      ? {
          amount,
          updated: new Date(observed).toISOString(),
          basis: row[2],
          provenance: 'official-export' as const,
        }
      : undefined;
  return {
    productId,
    url: `https://www.cardmarket.com/en/Pokemon/Products?idProduct=${productId}`,
    price,
  };
}

/** Test helper: no production UI or writes. */
export function resetOfficialCardmarketCacheForTest(): void {
  cache = undefined;
}
